recipes.bash:
diamond blastp -q 03_annotation/${SAMPLE}.faa -d ${NR_DMND} \
  -o 03_annotation/${SAMPLE}.nr.m8 -f 6 qseqid sseqid pident length evalue bitscore \
  --very-sensitive -p ${THREADS}

usage.code:
interproscan.sh -i anno/${SAMPLE}.faa -f TSV -appl Pfam,PANTHER,CDD \
  -o anno/${SAMPLE}.interpro.fast --cpu ${THREADS}
# 裁剪后「没有命中」只代表这些库没命中，不能写成「没有已知结构域」

diamond makedb --in CAZyDB.faa --db cazydb.dmnd --threads ${THREADS}
diamond blastp -q anno/${SAMPLE}.faa -d cazydb.dmnd -o anno/${SAMPLE}.cazy.m8 \
  -f 6 qseqid sseqid pident length qlen slen evalue bitscore \
  --max-target-seqs 5 --id 30 --query-cover 50 -p ${THREADS}
